def sliding_window_max(nums, k):
    if k <= 0 or k > len(nums):
        raise ValueError("k must be positive and less than or equal to the length of nums")
    deque = []
    result = []
    for i, num in enumerate(nums):
        while deque and nums[deque[-1]] <= num:
            deque.pop()
        deque.append(i)
        if deque[0] == i - k:
            deque.pop(0)
        if i >= k - 1:
            result.append(nums[deque[0]])
    return result
